 shell('Cases',`<a href="#Cases">← BURP Queue</a><div class="heading"><div><h1>${esc(c.display_name||c.brand_name||'Business identity review')}</h1><p>${esc(q?factualTitle(q,verificationOnly):c.issue_summary)}</p><p>${badge(c.priority)} ${badge(c.status)} · ${esc(age(c.created_at))} old · Assigned to ${esc(enums.administrators.find(a=>a.user_id===c.assigned_to_user_id)?.display_name||'Unassigned')}</p></div></div>${q?factualPanel(displayQuestion,verificationOnly):`<section class="panel human-decision"><h2>${esc(c.issue_summary)}</h2><p>${esc(c.recommended_resolution)}</p>${c.blocking?'<p>Resolve the identity or minimum-data question through the linked ingestion record below.</p>':''}${c.affected_fields.map(f=>`<h3>${esc(nice(f))}</h3><p>Current: ${esc(humanValue(f,c.active_fields.find(x=>x.field===f)?.active_value))}</p>${c.candidates.filter(x=>x.field===f).map(v=>`<p>Alternative: ${esc(humanValue(f,v.value))}<br>${esc(v.evidence_summary)}</p>`).join('')}`).join('')}${c.ingestion_jobs.map(j=>`<p><a href="#ingestion/${esc(j.id)}">Review ingestion decision</a></p>`).join('')}${!closed&&!c.blocking?'<button data-generic-resolve>Resolve — no data change</button>':''}</section>`}<div class="detail-grid"><div>${businessSummary(b,c)}${c.verification_links?.length?`<details class="panel"><summary>Linked Verification (${c.verification_links.length})</summary>${c.verification_links.map(l=>`<p><a href="#ops/verification/${esc(l.task_id)}">View Verification task</a></p>`).join('')}</details>`:''}<details class="panel"><summary>Evidence and technical details</summary><p>${esc(c.system_decision)}</p><p>${esc(c.decision_reason)}</p>${c.evidence.map(e=>`<details><summary>${esc(e.summary||e.source_type)}</summary>${opsJSON(e.payload)}</details>`).join('')}${opsJSON({relationships:c.relationships,case:id,origin:c.origin})}</details>${humanHistory(c.audit)}</div><section class="panel"><h2>Case controls</h2><label class="stack">Assigned to<select id="assignee">${opts(enums.administrators.map(a=>({value:a.user_id,label:a.display_name})),c.assigned_to_user_id,'Unassigned')}</select></label><button id="assign" ${closed?'disabled':''}>Assign</button><label class="stack">Raise priority<select id="priority">${opts(enums.priorities.filter(p=>enums.priorities.indexOf(p)<enums.priorities.indexOf(c.priority)),null,'Choose higher priority')}</select></label><button id="escalate" ${closed?'disabled':''}>Raise priority</button><label class="stack">Note<textarea id="note"></textarea></label><button id="save-note">Add note</button><div class="human-actions"><button data-review ${closed?'disabled':''}>Start Review</button>${!q?`<button data-defer ${closed?'disabled':''}>Defer</button>`:''}</div>${closed?`<p>${esc(c.resolution||c.status)} · ${esc(c.resolution_notes||'')}</p>`:''}</section></div>`);
 document.querySelector('#assign').onclick=()=>mutate('assign',{assigned_to_user_id:document.querySelector('#assignee').value});document.querySelector('#escalate').onclick=()=>mutate('escalate',{priority:document.querySelector('#priority').value});document.querySelector('#save-note').onclick=()=>mutate('note');document.querySelector('[data-review]').onclick=()=>mutate('review');document.querySelector('[data-defer]')?.addEventListener('click',()=>mutate('defer'));document.querySelector('[data-generic-resolve]')?.addEventListener('click',()=>mutate('no_action'));
 if(q)bindFactual(displayQuestion,{verify:verificationOnly,task:linkedTask,reload:()=>detail(id)});bindBusinessEditor(b,()=>detail(id));
