const legacyHumanOpsDetail=opsDetail;
opsDetail=async(kind,target)=>{
 if(kind!=='verification')return legacyHumanOpsDetail(kind,target);
 const d=await api(opsURL(kind,{target})),t=d.task,q=d.question;
 if(t.requirement!=='fact')return legacyHumanOpsDetail(kind,target);
 const question=q||{field:t.type,proposed:d.business[t.type],active:d.business[t.type],effective:true,state:t.status==='resolved'?'Resolved':t.status==='superseded'?'Superseded':'Pending',votes:[],active_revision:d.business.fact_revisions?.[t.type]||d.business.locations?.find(l=>l.id===t.location)?.revision||0,source:{provider:'Existing Business record'}};
 shell('Verification',`<a href="#Verification">← Verification</a><h1>${esc(d.business.name||t.business_name)}</h1><p>${esc(t.subject)} · ${badge(t.priority)} ${badge(t.status)} · ${esc(age(t.created))} old</p>${factualPanel(question,true)}<div class="detail-grid"><div>${businessSummary(d.business)}${d.case_links.length?`<details class="panel"><summary>Linked cases</summary>${d.case_links.map(l=>`<p><a href="#case/${esc(l.case_id)}">View case</a></p>`).join('')}</details>`:''}${humanHistory(d.fact_history)}</div><div>${opsWorkflow(d)}</div></div>`);
 bindFactual(question,{verify:true,task:t,reload:()=>opsDetail(kind,target)});bindBusinessEditor(d.business,()=>opsDetail(kind,target));opsBindAction(document.querySelector('#ops-workflow'),kind,target,d.workspace_version,()=>opsDetail(kind,target),()=>({action:'workflow'}));
};
