// Structured current-fact editors keep operator actions out of raw JSON.
function readableFacts(v){if(v==null)return 'Unknown';if(Array.isArray(v))return v.map(readableFacts).join('; ')||'Unknown';if(typeof v==='object')return Object.entries(v).map(([k,x])=>`${nice(k)}: ${readableFacts(x)}`).join(', ')||'Unknown';return String(v);}
function factLines(field,v){if(field==='ingredients')return (v||[]).map(x=>typeof x==='string'?x:x.name||x.text||'').filter(Boolean).join('\n');if(field==='allergens')return (v||[]).map(x=>typeof x==='string'?`contains: ${x}`:`${x.kind||Object.keys(x)[0]}: ${x.text||Object.values(x)[0]}`).join('\n');return Object.entries(v||{}).map(([k,x])=>`${k}: ${String(x)}`).join('\n');}
function typedFactEditor(field,v={},ctx={}){
 if(field==='price')return `<label class="stack">Current price (USD)<input data-price inputmode="decimal" value="${esc(v?.amount_minor==null?'':(Number(v.amount_minor)/100).toFixed(2))}" required></label><label><input data-zero type="checkbox" ${v?.explicit_zero?'checked':''}> Explicitly confirmed free Item</label>`;
 if(field==='menu_item')return `<label class="stack">Local Item name<input data-item-name value="${esc(v?.name||'')}"></label><label class="stack">Local availability<select data-item-state>${['observed_offered','observed_not_offered','temporarily_unavailable','unknown'].map(x=>`<option value="${x}" ${x===v?.state?'selected':''}>${esc(nice(x))}</option>`).join('')}</select></label>`;
 if(field==='nutrition')return `<label class="stack">Exact serving<input data-serving value="${esc(ctx?.serving||v?.serving||'')}" required readonly></label><label class="stack">Serving quantity<input data-serving-quantity type="number" min="0.001" step="any" value="${esc(v?.serving_quantity??'')}"></label><label class="stack">Serving unit<input data-serving-unit value="${esc(v?.serving_unit||'')}"></label><p>Published nutrient values only. A blank value remains Unknown.</p>${(v?.nutrients||[]).map(n=>`<label class="stack">${esc(nice(n.key))} (${esc(n.unit)})<input data-nutrient="${esc(n.key)}" data-unit="${esc(n.unit)}" data-daily-value="${esc(n.daily_value??'')}" type="number" min="0" step="any" value="${esc(n.amount??'')}"></label>`).join('')}${['ingredients','allergens','dietary'].map(f=>typedFactEditor(f,v?.[f])).join('')}`;
 return `<label class="stack">${esc(nice(field))}<textarea data-facts="${field}" placeholder="${field==='ingredients'?'One ingredient per line':field==='allergens'?'contains: milk or may_contain: wheat':'Explicit supported fact: true, false or unknown'}">${esc(factLines(field,v))}</textarea></label>`;
}
function readTypedFact(target,field){
 if(field==='price'){const raw=target.querySelector('[data-price]').value.trim();if(!/^\d+(?:\.\d{1,2})?$/.test(raw))throw Error('Enter a valid USD amount.');const amount_minor=Math.round(Number(raw)*100),explicit_zero=target.querySelector('[data-zero]').checked;if(!Number.isSafeInteger(amount_minor)||amount_minor===0&&!explicit_zero)throw Error('A zero price requires explicit confirmation.');return {amount_minor,currency:'USD',explicit_zero};}
 if(field==='menu_item')return {name:target.querySelector('[data-item-name]').value.trim(),state:target.querySelector('[data-item-state]').value};
 if(field==='nutrition'){const qty=target.querySelector('[data-serving-quantity]').value,unit=target.querySelector('[data-serving-unit]').value.trim();if(qty&&(!unit||Number(qty)<=0))throw Error('Positive quantity and serving unit required.');return {serving:target.querySelector('[data-serving]').value,serving_quantity:qty?Number(qty):null,serving_unit:unit||null,measurement:'published',nutrients:[...target.querySelectorAll('[data-nutrient]')].filter(el=>el.value!=='').map(el=>({key:el.dataset.nutrient,unit:el.dataset.unit,amount:Number(el.value),...(el.dataset.dailyValue?{daily_value:Number(el.dataset.dailyValue)}:{})})),ingredients:readTypedFact(target,'ingredients'),allergens:readTypedFact(target,'allergens'),dietary:readTypedFact(target,'dietary')};}
 const lines=target.querySelector(`[data-facts="${field}"]`).value.split('\n').map(x=>x.trim()).filter(Boolean);
 if(field==='ingredients')return lines.map(name=>({name}));
 if(field==='allergens')return lines.map(line=>{const m=line.match(/^(contains|may_contain|free_from|advisory):\s*(.+)$/);if(!m)throw Error('Use contains:, may_contain:, free_from: or advisory: with the explicit declaration.');return {kind:m[1],text:m[2]};});
 return Object.fromEntries(lines.map(line=>{const m=line.match(/^([^:]+):\s*(true|false|unknown)$/);if(!m)throw Error('Use explicit dietary fact: true, false or unknown.');return [m[1].trim(),m[2]==='unknown'?null:m[2]==='true'];}));
}
// The existing environment stays paused until a separate ingestion command.
const currentPersistenceShell=shell;
shell=function(section,html){currentPersistenceShell(section,html);if(section!=='Ingestion'||!window.FeediaHosted?.rpc)return;const content=document.querySelector('.content');window.FeediaHosted.rpc('fd_persistence_status').then(p=>{if(!content?.isConnected||p.acquisition_enabled)return;const banner=document.createElement('section');banner.className='panel';banner.innerHTML='<h2>Acquisition paused</h2><p>Source acquisition and processing are disabled. A separate Brand ingestion command is required to enable them.</p>';content.prepend(banner);content.querySelectorAll('form:not(#iv-filter):not(#ops-filters) button,[data-executor-action],[data-iv-control],#iv-process-release').forEach(b=>b.disabled=true);}).catch(()=>{});};
